// Extrae texto del mail, matchea la card (Ref en asunto/cuerpo, link, o nro de ticket conocido)
// y detecta si la mesa dio por resuelto el caso.
function b64url(s) { try { return Buffer.from((s || '').replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8'); } catch (e) { return ''; } }
function collectText(payload, out) {
  if (!payload) return;
  if (payload.mimeType === 'text/plain' && payload.body && payload.body.data) out.plain.push(b64url(payload.body.data));
  if (payload.mimeType === 'text/html' && payload.body && payload.body.data) out.html.push(b64url(payload.body.data));
  for (const p of payload.parts || []) collectText(p, out);
}
const sd = $getWorkflowStaticData('global');
if (!sd.ticketMap) sd.ticketMap = {};
if (!sd.ticketMap['271212']) sd.ticketMap['271212'] = 'tAnZsa3n'; // seed: primer ticket real, mapeado a mano
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const raw = items[i].json;
  const meta = $('Nueva Respuesta Mesa').all()[i] ? $('Nueva Respuesta Mesa').all()[i].json : {};
  const buf = { plain: [], html: [] };
  collectText(raw.payload, buf);
  let texto = buf.plain.join('\n');
  if (!texto && typeof raw.text === 'string' && raw.text) texto = raw.text;
  if (!texto && typeof raw.textPlain === 'string' && raw.textPlain) texto = raw.textPlain;
  if (!texto) {
    const h = buf.html.join('\n') || raw.html || raw.textHtml || raw.textAsHtml || '';
    if (h) texto = String(h).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
  }
  if (!texto) texto = raw.snippet || meta.snippet || '';
  const headers = {};
  for (const h of (raw.payload && raw.payload.headers) || []) headers[h.name.toLowerCase()] = h.value;
  const subject = headers['subject'] || meta.Subject || meta.subject || '(sin asunto)';
  const from = headers['from'] || meta.From || meta.from || '';
  let mCard = (subject + '\n' + texto).match(/\(Ref[:\s]+([A-Za-z0-9]{6,12})\)/i);
  if (!mCard) mCard = texto.match(/https:\/\/trello\.com\/c\/([A-Za-z0-9]+)/);
  const mTicket = (subject + '\n' + texto).match(/(?:ticket|caso|incidente|solicitud|numero|nÃºmero|nro\.?|#)\s*[:#]?\s*(\d{3,10})/i);
  let cardShort = mCard ? mCard[1] : '';
  const ticketNum = mTicket ? mTicket[1] : '';
  if (cardShort && ticketNum) {
    sd.ticketMap[ticketNum] = cardShort;
    const ks = Object.keys(sd.ticketMap);
    if (ks.length > 200) { for (const k of ks.slice(0, ks.length - 150)) delete sd.ticketMap[k]; }
  }
  if (!cardShort && ticketNum && sd.ticketMap[ticketNum]) cardShort = sd.ticketMap[ticketNum];
  const esResuelto = /(resuelt|solucionad|cerrad|finalizad)/i.test(subject + ' ' + texto.slice(0, 3000));
  const resumen = texto.replace(/\s+/g, ' ').trim().slice(0, 500);
  out.push({ json: { cardShort, ticketNum, esResuelto, from, subject, resumen } });
}
return out;

