  if (!mChat) continue; // card sin origen WhatsApp
  const nombre = (d.cardName || '').replace(/^[^0-9A-Za-z\[Ã€-Å¿]+\s*/, '');
  out.push({ json: {
    recipient: mChat[1],
    message: `ðŸ“‹ Novedad de la mesa de ayuda sobre tu requerimiento \"${nombre}\":\n${d.subject}${d.ticketNum ? ' (Ticket #' + d.ticketNum + ')' : ''}\n\n${(d.resumen || '').slice(0, 250)}`
  } });
}
return out;

const src = $('Parsear Respuesta').item.json;
const cards = ($json && $json.cards) || [];
const cardShort = cards.length ? (cards[0].shortLink || cards[0].id) : '';
if (cardShort && src.ticketNum) {
  const sd = $getWorkflowStaticData('global');
  if (!sd.ticketMap) sd.ticketMap = {};
  sd.ticketMap[src.ticketNum] = cardShort;
}
return { json: { ...src, cardShort } };

